//! BASHH paginated guideline listings, source detail pages and independently linked assets.
use super::{common,Adapter,PlanRow};
use crate::guidelines::doc::{GuidelineDoc,Rights};
use crate::guidelines::fetch::{Fetched,Fetcher};
use crate::guidelines::html::{sel,text_of};
use crate::guidelines::registry::SourceEntry;
use anyhow::{bail,Context,Result};
use scraper::Html;
use serde_json::json;
use std::collections::{HashSet,VecDeque};
use url::Url;
pub struct Bashh;
fn listings(html:&str,base:&Url)->Result<(Vec<(String,String)>,Vec<String>)>{let d=Html::parse_document(html);if d.select(&sel(".resource-listings")).next().is_none(){bail!("BASHH resource listing missing");}let mut items=vec![];let mut pages=vec![];let mut seen=HashSet::new();
 for a in d.select(&sel(".resource-listings .listing h3 a[href]")){if let Some(u)=common::link(base,a.value().attr("href").unwrap_or_default()){let p=Url::parse(&u)?;let t=text_of(&a);if p.origin()==base.origin()&&p.path().starts_with("/resources/")&&!t.is_empty()&&seen.insert(u.clone()){items.push((u,t));}}}
 for a in d.select(&sel("ul.pagination a[href]")){if let Some(u)=common::link(base,a.value().attr("href").unwrap_or_default()){let p=Url::parse(&u)?;if p.origin()==base.origin()&&p.path()==base.path()&&p.query_pairs().all(|(k,v)|k=="page"&&v.chars().all(|c|c.is_ascii_digit()))&&seen.insert(u.clone()){pages.push(u)}}}Ok((items,pages))}
fn detail(html:&str,base:&Url)->Result<Vec<(String,String)>>{let d=Html::parse_document(html);let mut seen=HashSet::new();let mut out=vec![];for a in d.select(&sel("a[href]")){let Some(url)=common::link(base,a.value().attr("href").unwrap_or_default())else{continue};let u=Url::parse(&url)?;if u.origin()!=base.origin()||!u.path().starts_with("/_userfiles/")||!u.path().to_lowercase().ends_with(".pdf"){continue;}let label=text_of(&a);if seen.insert(url.clone()){out.push((url,label));}}if out.is_empty(){bail!("BASHH detail has no observed publisher PDF link");}Ok(out)}
fn pdf_complete(f:&Fetched)->bool{f.is_pdf()&&f.body.iter().rev().take(2048).copied().collect::<Vec<_>>().windows(5).any(|x|x==b"FOE%%")}
fn unresolved(src:&SourceEntry,url:String,error:String)->PlanRow{PlanRow{source_id:src.id.clone(),doc_key:format!("{}-unresolved",common::short_hash(&url)),url,title:None,rendition:None,version:None,extra:json!({"discovery_error":error})}}
#[async_trait::async_trait]impl Adapter for Bashh{
 async fn discover(&self,src:&SourceEntry,f:&Fetcher,limit:Option<usize>)->Result<Vec<PlanRow>>{if limit==Some(0){return Ok(vec![])}let root=src.catalog_url.as_deref().context("BASHH catalog missing")?;let first=f.get_ok(root).await?;let base=Url::parse(&first.record.final_url)?;let mut pages:VecDeque<String>=vec![root.to_string()].into();let mut page_seen=HashSet::new();let mut item_seen=HashSet::new();let mut rows=vec![];let mut deferred=vec![];
  while let Some(list)=pages.pop_front(){if !page_seen.insert(list.clone()){continue;}if page_seen.len()>100{bail!("BASHH pagination exceeded 100 pages");}let p=match f.get_ok(&list).await{Ok(p)=>p,Err(e)=>{deferred.push(unresolved(src,list,format!("{e:#}")));continue;}};let b=Url::parse(&p.record.final_url)?;let (items,next)=listings(&p.text(),&b)?;for u in next{if !page_seen.contains(&u){pages.push_back(u)}}
   for (url,title) in items{if !item_seen.insert(url.clone()){continue;}let detail_page=match f.get_ok(&url).await{Ok(x)=>x,Err(e)=>{deferred.push(unresolved(src,url,format!("{e:#}")));continue;}};let b=Url::parse(&detail_page.record.final_url)?;if b.origin()!=base.origin(){deferred.push(unresolved(src,url,"detail crossed source origin".into()));continue;}let links=match detail(&detail_page.text(),&b){Ok(x)=>x,Err(e)=>{deferred.push(unresolved(src,url,format!("{e:#}")));continue;}};
    for(pdf,label)in links{let data=match f.get_ok(&pdf).await{Ok(x)if pdf_complete(&x)=>x,Ok(_)=>{deferred.push(unresolved(src,pdf,"not a complete PDF".into()));continue;},Err(e)=>{deferred.push(unresolved(src,pdf,format!("{e:#}")));continue;}};let key=common::short_hash(&pdf);rows.push(PlanRow{source_id:src.id.clone(),doc_key:format!("{key}-{}",&data.record.sha256[..12]),url:pdf,title:Some(title.clone()),rendition:Some("pdf".into()),version:None,extra:json!({"work_key":key,"detail_url":url,"link_label":label,"pdf_sha256":data.record.sha256,"detail_sha256":detail_page.record.sha256,"catalog_fetch":first.record,"detail_fetch":detail_page.record})});if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}}
   }
  }let rem=limit.map(|n|n.saturating_sub(rows.len())).unwrap_or(usize::MAX);rows.extend(deferred.into_iter().take(rem));Ok(rows)}
 async fn extract(&self,src:&SourceEntry,f:&Fetcher,row:&PlanRow)->Result<GuidelineDoc>{if let Some(e)=row.extra["discovery_error"].as_str(){bail!("BASHH source unresolved: {e}");}let detail_url=row.extra["detail_url"].as_str().context("detail URL missing")?;let d=f.get_ok(detail_url).await?;if row.extra["detail_sha256"].as_str().is_some_and(|x|x!=d.record.sha256){bail!("BASHH detail changed since discovery");}if !detail(&d.text(),&Url::parse(&d.record.final_url)?)?.iter().any(|(u,_)|u==&row.url){bail!("BASHH PDF no longer linked by detail page");}let pdf=f.get_ok(&row.url).await?;if !pdf_complete(&pdf){bail!("BASHH PDF incomplete");}if row.extra["pdf_sha256"].as_str().is_some_and(|x|x!=pdf.record.sha256){bail!("BASHH PDF changed since discovery");}let (blocks,mut warnings,_)=super::static_list::blocks_for(&pdf,None,0).await?;if blocks.is_empty(){bail!("BASHH PDF has no mapped text");}
  warnings.push("Source detail and linked PDF are separate assets; label and clinical role are retained without assuming every PDF is a full guideline. Generic PDF conversion does not verify tables, grades, figures or page order.".into());let mut fetches=vec![];if let Ok(r)=serde_json::from_value::<crate::guidelines::doc::FetchRecord>(row.extra["catalog_fetch"].clone()){fetches.push(r)}fetches.push(d.record);fetches.push(pdf.record);Ok(GuidelineDoc{source_id:src.id.clone(),doc_key:row.doc_key.clone(),work_key:row.extra["work_key"].as_str().map(String::from),title:row.title.clone().unwrap_or_default(),url:row.url.clone(),item_type:Some("source_linked_pdf".into()),status:"unknown".into(),rights:Rights{status:"unknown".into(),note:Some("PDF, publisher article, and related materials have independent unverified rights.".into()),..Default::default()},search_metadata:json!({"detail_url":detail_url,"source_pdf_link_label":row.extra["link_label"]}),blocks,fetches,warnings,..Default::default()})}
}
#[cfg(all(test, feature = "guideline-fixtures"))]mod tests{use super::*;const C:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/bashh/catalog.html"));#[test]fn genuine_first_listing_and_source_pagination(){let base=Url::parse("https://www.bashh.org/resources/guidelines/").unwrap();let(items,pages)=listings(C,&base).unwrap();assert!(items.iter().any(|(u,_)|u.ends_with("/resources/23/anogenital_herpes_2024_updated_guideline")));assert!(pages.iter().any(|u|u.ends_with("?page=2")));assert!(pages.iter().any(|u|u.ends_with("?page=6")));assert!(listings("<html>empty</html>",&base).is_err());}}

#[cfg(all(test, feature = "guideline-fixtures"))] mod acquired_graph_test {
 use super::*;
 const TOPIC:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/bashh/herpes-topic.html"));
 const PAGE2:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/bashh/catalog-page2.html"));
 #[test] fn genuine_pagination_and_herpes_pdf_path(){
  let page=Url::parse("https://www.bashh.org/resources/guidelines/?page=2").unwrap();let (items,pages)=listings(PAGE2,&page).unwrap();assert!(!items.is_empty());assert!(!pages.is_empty());
  let topic=Url::parse("https://www.bashh.org/resources/23/anogenital_herpes_2024_updated_guideline").unwrap();let links=detail(TOPIC,&topic).unwrap();assert!(links.iter().any(|(u,l)|u.ends_with("/pateletal2024britishassociationofsexualhealthandhivuknationalguidelineforthemanagementofanogenital.pdf")&&l=="here"));
 }
}
